    for(const auto& row:state.contracts.rows()){const auto& contract=row.second;const auto& terms=contract.frozen_terms;if(authority){auto permission=read_task_public_account_execution(common,state,catalog,authority,contract.id);if(!permission.ok)return {false,{},permission.error};}auto* task=contract.current_task_id?state.tasks.find(*contract.current_task_id):nullptr;auto* offer=task?state.offer_instances.find(task->offer_id):nullptr;auto* wallet=task?common.wallet(task->budget_wallet_id):nullptr;auto* source=common.wallet(terms.source_wallet_id);auto* reward=common.wallet(terms.reward_wallet_id);auto* payee=common.wallet(terms.payee_wallet_id);if(static_cast<Integer>(contract.status)<0||static_cast<Integer>(contract.status)>3||contract.id!=row.first||!task||!offer||!wallet||!source||!reward||!payee||!task->contract_id||*task->contract_id!=contract.id||!task->offer_ref||task->offer_ref->kind!=OfferRef::Kind::runtime||task->offer_ref->id!=offer->id||!contract.executor_actor_id||*contract.executor_actor_id!=task->assignee||!common.actor(*contract.executor_actor_id)||!same_terms(terms,*offer)||!bound_claims.insert(contract.source_binding.claim_id).second||contract.source_binding.contract_id!=contract.id||contract.source_binding.need_id!=offer->source_need_id||contract.source_binding.affair_id.empty()||contract.source_binding.source_revision<1||terms.agreed_quantity<=0||terms.purchase_budget_cap<0||terms.reward_total<0||terms.deadline_tick<task->accepted_tick||task->deadline_tick!=terms.deadline_tick||terms.payment_policy!="delivered_on_time_pro_rata_v1"||terms.unused_budget_policy!="return_to_issuer"||terms.late_reward_policy!="zero"||terms.cancellation_policy_id!="return_actual_cargo_v1"||(terms.personal_advance_allowed&&!state.personal_advances)||!common.inventory(terms.target_inventory_id)||terms.item_id!=terms.definition.goal.item_id||terms.quantity_unit.empty()||terms.terms_version!=offer->terms_version||terms.source_wallet_id!=offer->funding_wallet_id||terms.reward_wallet_id!=offer->reward_wallet_id||(!authority&&(!owner_equal(source->owner,contract.issuer)||!owner_equal(reward->owner,contract.issuer)))||!owner_equal(contract.issuer,offer->issuer)||wallet->owner.kind!=Owner::Kind::task||wallet->owner.id!=task->id||contract.delivered_quantity!=delivered[contract.id]||contract.eligible_delivered_quantity!=eligible[contract.id]||contract.delivered_quantity>terms.agreed_quantity||contract.eligible_delivered_quantity>contract.delivered_quantity||contract.paid_reward<0||contract.refunded_reward<0||contract.refunded_budget<0||contract.refunded_budget>terms.purchase_budget_cap||contract.paid_reward>terms.reward_total||contract.refunded_reward>terms.reward_total-contract.paid_reward)return common_failure("InvalidTaskContract",row.first);if((contract.assignee.kind==SubjectKind::actor&&(terms.payee_wallet_id!=common.actor(*contract.executor_actor_id)->wallet_id||payee->owner.kind!=Owner::Kind::actor||payee->owner.id!=contract.assignee.id))||(contract.assignee.kind==SubjectKind::organization&&(payee->owner.kind!=Owner::Kind::organization||payee->owner.id!=contract.assignee.id)))return common_failure("ContractPayeeMismatch",row.first);if((contract.assignee.kind==SubjectKind::actor&&(contract.assignee.id!=task->assignee||contract.accepted_authority))||(contract.assignee.kind==SubjectKind::organization&&(!contract.accepted_authority||contract.accepted_authority->organization_id!=contract.assignee.id||!common.actor(contract.accepted_authority->actor_id)||contract.accepted_authority->office_id.empty()||contract.accepted_authority->authority_epoch<1))||contract.assignee.kind==SubjectKind::cohort)return common_failure("ContractAssigneeMismatch",row.first);auto due_quote=task_prorata(terms.reward_total,contract.eligible_delivered_quantity,terms.agreed_quantity);if(!due_quote.ok)return {false,{},due_quote.error};const auto due=due_quote.value;const auto remaining_reward=terms.reward_total-contract.paid_reward-contract.refunded_reward;Integer outstanding_advance=0;if(terms.personal_advance_allowed){auto advance=read_task_personal_advance_summary(common,state,*state.personal_advances,contract.id);if(!advance.ok)return {false,{},advance.error};outstanding_advance=advance.value.paid-advance.value.repaid;}if(contract.paid_reward>due||held_reward(*wallet,contract.id)!=remaining_reward||wallet->balance<remaining_reward||(wallet->balance-remaining_reward>terms.purchase_budget_cap-contract.refunded_budget&&wallet->balance-remaining_reward-(terms.purchase_budget_cap-contract.refunded_budget)>outstanding_advance))return common_failure("ContractEscrowMismatch",row.first);if(!contract.execution_stopped&&(contract.status==ContractStatus::settling||contract.status==ContractStatus::settled||!contract.stop_reason.empty()||contract.paid_reward||contract.refunded_budget||contract.refunded_reward))return common_failure("InvalidContractLifecycle",row.first);if(contract.deadline_closure){auto close=read_task_quantity_deadline_source_moment(common,state,{"tasks",task_quantity_deadline_closed_kind,contract.deadline_closure->source_id},1,life);if(!close.ok)return {false,{},close.error};}else if(task->record_kind==TaskRecordKind::exact_quantity&&contract.stop_reason=="expired")return common_failure("QuantityDeadlineOriginalCloseRequired",row.first,ErrorKind::unsupported_capability);if(contract.execution_stopped&&contract.stop_reason!="cancelled"&&contract.stop_reason!="expired"&&contract.stop_reason!="fulfilled"&&contract.stop_reason!="cargo_loss")return common_failure("InvalidContractStopReason",row.first);std::vector<StableId> cargo;for(const auto& inventory:common.state().inventories.rows())for(const auto& lot:inventory.second.lots)if(lot.quantity>0&&lot.owner.kind==Owner::Kind::task&&(lot.owner.id==task->id||contains(contract.historical_task_ids,lot.owner.id))){if(lot.item_id!=terms.item_id)return common_failure("UnauthorizedContractGoods",lot.id);cargo.push_back(inventory.first);break;}if(contract.status==ContractStatus::settled){if(!contract.execution_stopped||!contract.settlement_id||*contract.settlement_id!=task->settlement_id||wallet->balance||!wallet->reserved.empty()||!cargo.empty()||!contract.restitution_refs.empty()||contract.paid_reward!=due)return common_failure("UnsettledContractClosed",row.first);for(const auto& action:state.actions.rows())if(action.second.task_id==task->id&&common.action(action.first))return common_failure("ActiveSettledContract",row.first);}else if(contract.settlement_id)return common_failure("PrematureContractSettlement",row.first);if(contract.status==ContractStatus::settling&&contract.restitution_refs!=cargo)return common_failure("MissingContractRestitution",row.first);}
